from itertools import combinations

def solve_m(m):
    """
    Checks if there exist two non-empty, disjoint subsets X and Y of {1, ..., m}
    such that sum(X) = sum(Y) = T = m(m+1)/6.
    """
    # 1. Calculate Target Sum T
    if (m * (m + 1)) % 6 != 0:
        return False, "T is not an integer"
    T = (m * (m + 1)) // 6

    S = list(range(1, m + 1))

    # Small m failure cases check
    if m == 2: 
        return False, "Failure case m=2: T=1. Only one non-empty subset sums to 1."
    if m == 3: 
        return False, "Failure case m=3: T=2. Only one non-empty subset sums to 2 ({2}), leaving no disjoint subset summing to 2."

    # 2. Find all non-empty subsets X summing to T
    subsets_X = []
    for k in range(1, m + 1): # Subset size k
        for X_candidate in combinations(S, k):
            if sum(X_candidate) == T:
                subsets_X.append(set(X_candidate))

    if not subsets_X:
        return False, "No subset X found summing to T"

    # 3. For each X, check if S \ X contains a non-empty subset Y summing to T
    for X in subsets_X:
        S_minus_X = [s for s in S if s not in X]

        # Iterate through all non-empty subsets Y of S \ X
        for k in range(1, len(S_minus_X) + 1):
            for Y_candidate_list in combinations(S_minus_X, k):
                Y_candidate = set(Y_candidate_list)

                if sum(Y_candidate) == T:
                    # Since Y is a subset of S \ X, X and Y are disjoint.
                    # Both X and Y are non-empty by construction (k>=1 for both).
                    return True, f"Success found for m={m}"

    return False, "No suitable disjoint subset Y found for any X"

# Run the check for m=1 to 100
count = 0
results = {}

for m in range(1, 101):
    result, details = solve_m(m)
    results[m] = result
    if result:
        count += 1

print(f"--- Final Count ---")
print(f"Total count of m <= 100 satisfying the conditions: {count}")
print("\n--- Documentation Snippet (m=1 to m=15) ---")
for m in range(1, 16):
    status = "YES" if results[m] else "NO"
    print(f"m={m} ({status}): {results[m][1]}")

